import sys
from collections import defaultdict

# Read and filter dictionary
with open("/workdir/data/dict.txt") as f:
    raw_words = [line.strip() for line in f]

valid_words = set()
for w in raw_words:
    if len(w) >= 4 and w.isalpha():
        w_lower = w.lower()
        valid_words.add(w_lower)

print(f"Total valid words (len>=4, alpha only): {len(valid_words)}")

# Create canonical form for each word
def canonical_form(word):
    mapping = {}
    result = []
    counter = 0
    for ch in word:
        if ch not in mapping:
            mapping[ch] = chr(ord('a') + counter)
            counter += 1
        result.append(mapping[ch])
    return "".join(result)

# Group words by canonical form
groups = defaultdict(list)
for w in valid_words:
    cf = canonical_form(w)
    groups[cf].append(w)

# Find groups with multiple words (potential pairs)
multi_groups = {k: v for k, v in groups.items() if len(v) >= 2}
print(f"Groups with 2+ words: {len(multi_groups)}")

# For each group, find all pairs and their mappings
# Then try to combine compatible mappings

# Let's try a greedy approach: pick pairs and build a mapping
all_pairs = []
for cf, words in multi_groups.items():
    for i in range(len(words)):
        for j in range(len(words)):
            if i != j:
                w1, w2 = words[i], words[j]
                # Check if they define a valid partial mapping
                mapping = {}
                reverse = {}
                valid = True
                for c1, c2 in zip(w1, w2):
                    if c1 in mapping:
                        if mapping[c1] != c2:
                            valid = False
                            break
                    else:
                        mapping[c1] = c2
                    if c2 in reverse:
                        if reverse[c2] != c1:
                            valid = False
                            break
                    else:
                        reverse[c2] = c1
                    if c1 == c2:  # derangement constraint
                        valid = False
                        break
                if valid:
                    all_pairs.append((w1, w2, dict(mapping)))

print(f"Total valid pairs: {len(all_pairs)}")

# Now try to find a set of compatible pairs that give us 50+ words with 24+ unique chars
# Greedy approach: sort pairs by number of new characters they contribute

# Sort pairs by number of unique characters (descending)
all_pairs.sort(key=lambda x: -len(x[2]))

# Try greedy selection
selected_pairs = []
current_mapping = {}
current_reverse = {}
selected_words = set()

for w1, w2, partial_map in all_pairs:
    if w1 in selected_words or w2 in selected_words:
        continue
    # Check compatibility with current mapping
    compatible = True
    new_map = dict(current_mapping)
    new_rev = dict(current_reverse)

    for c1, c2 in partial_map.items():
        if c1 in new_map:
            if new_map[c1] != c2:
                compatible = False
                break
        else:
            if c2 in new_rev:
                compatible = False
                break
            new_map[c1] = c2
            new_rev[c2] = c1
        if c1 == c2:
            compatible = False
            break

    if compatible:
        current_mapping = new_map
        current_reverse = new_rev
        selected_pairs.append((w1, w2, partial_map))
        selected_words.add(w1)
        selected_words.add(w2)

        if len(selected_words) >= 100:  # aim for more than 50
            break

print(f"Selected words: {len(selected_words)}")
if len(selected_words) >= 50:
    all_chars = set()
    for w in selected_words:
        all_chars.update(w)
    print(f"Unique characters: {len(all_chars)}")
    print(f"Mapping so far: {current_mapping}")
    print(f"Words: {sorted(selected_words)[:60]}")
else:
    print("Not enough words found with greedy approach")
